questionvariables.text:
/*Question Variables*/
aa:rand(70)+20;/*percentage of  inhabitants becoming sick*/
bb:100;
cc:rand(20)+10;/*persons admitted to an emergency ward*/
dd:(100-aa)/100;/*P(A)*/
dd_1:decimalplaces(float(dd),4);
ee_1:1-dd_1;/*P(A^C)*/
ee:decimalplaces(ee_1,2);
ff:cc/bb;/*P(B|A^C)*/
ff_1:decimalplaces(float(ff),4);
gg:dd*0+ee*ff;/*P(B)*/
/*Model answer*/
ta:decimalplaces(float(gg),2);
ta_1:float(cc/100);

feedbackvariables.text:
/*Node 1 checks for correct answer*/
/*Node 2: mistake:Interchanging the P(A) with P(A^C)*/
mistake_2_1:aa/100;/*P(A)*/
mistake_2_2:decimalplaces(float(mistake_2_1),2);
mistake_2_3:dd_1;/*P(A^C)*/
mistake_2_4:mistake_2_1*0+mistake_2_3*ff;
mistake_2:decimalplaces(mistake_2_4,2);
